export class NavigationUtilities<T extends HTMLElement> {
  isLeafItem(item: T, selectors: string) {
    return item.querySelectorAll(selectors).length === 0;
  }

  hasActiveChildItems(item: T, selectors: string): boolean {
    const childItems = item.querySelectorAll(selectors);

    return Array.from(childItems).some((child: HTMLElement) => {
      return child.hasAttribute('active');
    });
  }

  getAllItems(element: HTMLElement, selectors: string): T[] {
    return Array.from(element.querySelectorAll(selectors)) as T[];
  }

  removeActiveFromAllItems(element: HTMLElement, selectors: string): void {
    this.getAllItems(element, selectors).forEach((el) => el.removeAttribute('active'));
  }

  setActiveItem(item: T): void {
    item.setAttribute('active', '');
  }

  removeActiveItem(item: T): void {
    item.removeAttribute('active');
  }

  toggleOpenState(item: T) {
    if (item.getAttribute('open') === '') {
      item.removeAttribute('open');
    } else {
      item.setAttribute('open', '');
    }
  }

  setAttribute(items: T[], name: string, value: string): void {
    items.forEach((item) => {
      item.setAttribute(name, value);
    });
  }

  removeAttribute(items: T[], name: string): void {
    items.forEach((item) => {
      item.removeAttribute(name);
    });
  }

  updateBooleanAttribute(items: T[], name: string, value: boolean): void {
    items.forEach((item) => {
      if (value) {
        item.setAttribute(name, '');
      } else {
        item.removeAttribute(name);
      }
    });
  }
}
